ur de {0}: încă {1} zile", ["today_frost_none"] = "Setează datele de îngheț în profilul grădinii ca să vezi numărătoarea.", ["today_ready_now"] = "gata de recoltat", ["today_ready_days"] = "în {0} zile · {1}", ["today_ready_weeks"] = "în aproximativ {0} săptămâni · {1}", ["today_wx_frost"] = "Îngheț prognozat {0} (minim {1}°C): acoperă plantele sensibile și adu ghivecele înăuntru.", ["today_wx_heat"] = "Caniculă prognozată {0} (maxim {1}°C): udă dimineața devreme și umbrește răsadurile.", ["today_wx_wind"] = "Vânt puternic prognozat {0} ({1} km/h): asigură ușa serei și pomii tineri.", ["today_wx_rain"] = "Ploaie așteptată azi ({0} mm): sari peste udatul stratelor.", ["today_welcome"] = "Bun venit!", ["today_welcome_sub"] = "Iată informațiile de azi despre gospodăria ta:", ["today_t_urgent"] = "urgente", ["today_t_open"] = "de făcut", ["today_t_water"] = "plante de udat", ["today_t_ready"] = "gata de recoltat", ["wx_clear"] = "Senin", ["wx_partly"] = "Parțial noros", ["wx_cloudy"] = "Noros", ["wx_fog"] = "Ceață", ["wx_drizzle"] = "Burniță", ["wx_rain"] = "Ploaie", ["wx_snow"] = "Ninsoare", ["wx_showers"] = "Averse", ["wx_storm"] = "Furtună", ["season_view"] = "Vezi grădina la o dată din trecut", ["season_now"] = "Înapoi la azi", ["season_info"] = "Grădina așa cum era pe {0} (aproximativ: culturile terminate dispar după timpul lor obișnuit de recoltare).", ["sensor_source"] = "Sursa de senzori", ["sensor_none"] = "(fără senzor)", ["sensor_help"] = "Alege locul ai cărui senzori măsoară acest strat: umiditatea solului apare ca un punct colorat pe plan și pe fișa plantei.", ["sensor_dry"] = "uscat", ["sensor_ok"] = "bună", ["sensor_wet"] = "umed", ["sensor_moisture"] = "Umiditatea solului {0}% ({1})", ["sensor_temp"] = "Aer {0}°C", ["gh_guide_title"] = "Prima configurare a Raspberry Pi, pas cu pas", ["gh_guide_intro"] = "Pi citește senzorii și îi trimite aici; aplicația decide ce să pornească și îi spune Pi-ului. Circa 45 de minute. Poți testa totul mai întâi cu senzori falși.", ["gh_guide_1"] = "1. Pune „Raspberry Pi OS Lite (64-bit)” pe un card SD cu Raspberry Pi Imager. În setările lui alege numele „greenhouse”, un utilizator și o parolă, Wi-Fi-ul tău și bifează Enable SSH. Pune cardul în Pi și alimentează-l.", ["gh_guide_2"] = "2. Pe acest PC deschide Windows Terminal și conectează-te la Pi (răspunde yes, apoi scrie parola):", ["gh_guide_3"] = "3. Mai jos bifează „Acceptă conexiuni de la Raspberry Pi” și apasă Aplică; permite firewall-ul pe rețele private. Adresa acestui PC în rețeaua ta:", ["gh_guide_4"] = "4. Copiază agentul pe Pi. Într-un al doilea terminal de pe acest PC, în folderul Garden Helper:", ["gh_open_folder"] = "Deschide folderul cu scriptul", ["gh_your_pc"] = "Acest PC:", ["gh_guide_5"] = "5. În terminalul conectat la Pi, testează conexiunea. Trebuie să răspundă „Connected”:", ["gh_guide_6"] = "6. Încearcă cu senzori falși. În câteva secunde casetele de mai sus încep să se miște. Oprește cu Ctrl+C.", ["gh_guide_7"] = "7. Conectează senzorii reali (DS18B20 pentru apă, BME280 pentru aer și umiditate) și pornește agentul cu --ds18b20 și/sau --bme280 în loc de --simulate. Relee: ventilație, ventilator, apă, pompă, lumină (vezi ghidul complet).", ["gh_guide_8"] = "8. Ca să pornească la boot, adaugă --print-service la comandă și salvează rezultatul ca /etc/systemd/system/greenhouse-agent.service, apoi: sudo systemctl enable --now greenhouse-agent. Pentru acces din afara casei folosește un VPN ca Tailscale; nu deschide niciodată portul în router.", ["gh_guide_safety"] = "Siguranță: cablarea pompelor, a vanelor sau a încălzitoarelor la rețea trebuie făcută de o persoană calificată, cu siguranță sau diferențial. Păstrează un termostat hardware ca ultimă apărare.", ["gh_guide_full"] = "Ghidul complet cu schemele de conectare descrise și un tabel de depanare este în docs\\RASPBERRY-PI-SETUP.md. Același agent poate alimenta orice loc, de exemplu senzori de sol pe un strat (alege-l ca Sursă de senzori în designerul de grădină).", ["gh_guide_missing"] = "Folderul cu scriptul nu a fost găsit lângă aplicație.", ["edit_help"] = "Remodelezi un loc: trage un colț ca să-l muți, apasă pe punctul dintre două colțuri ca să adaugi un colț, clic dreapta pe un colț ca să-l ștergi. Schimbările se salvează pe loc.", ["edit_open_plan"] = "Deschide planul", ["edit_done"] = "Gata", ["edit_corner_tip"] = "Trage ca să muți. Clic dreapta ca să ștergi acest colț.", ["edit_add_tip"] = "Apasă ca să adaugi un colț aici", ["edit_min_corners"] = "Un loc are nevoie de cel puțin 3 colțuri.", ["edit_delete_confirm"] = "Ștergi locul „{0}” de pe hartă, cu notele lui?", ["gh_howto"] = "Cum configurezi Raspberry Pi (ghid pas cu pas)", ["gh_howto_tip"] = "Deschide ghidul complet pentru prima configurare, cu adresa, tokenul și numărul locului deja completate. Ghidul este în engleză.", ["pi_guide_title"] = "Ghid Raspberry Pi", ["pi_guide_back"] = "← Înapoi la seră", ["welcome_title"] = "Bun venit în Garden Helper!", ["welcome_sub"] = "Hai să-ți configurăm gospodăria într-un minut. Poți schimba totul mai târziu.", ["welcome_default_name"] = "Gospodăria mea", ["welcome_s1"] = "1. Gospodăria ta", ["welcome_name"] = "Nume", ["welcome_find"] = "Caută satul sau orașul tău (opțional: cere internet, trimite doar acest nume)", ["welcome_search"] = "Caută", ["welcome_search_tip"] = "Caută locul cu serviciul gratuit Open-Meteo. Nu se trimite nimic altceva.", ["welcome_country"] = "Țara", ["welcome_region"] = "Județ / regiune", ["welcome_frost"] = "Date tipice de îngheț", ["welcome_spring"] = "Ultimul îngheț de primăvară", ["welcome_autumn"] = "Primul îngheț de toamnă", ["welcome_frost_help"] = "Folosite la stabilirea momentului semănatului și plantatului. Întreabă un vecin sau folosește datele obișnuite din zona ta; le poți rafina în profilul grădinii.", ["welcome_s2"] = "2. Animalele pe care le ții", ["welcome_animals_help"] = "Bifează ce ții și câte. Detaliile și jurnalul zilnic le poți adăuga mai târziu.", ["welcome_how_many"] = "Câte", ["welcome_s3"] = "3. Ce vrei să cultivi", ["welcome_crops_help"] = "Bifează culturile pe care vrei să le faci. Primești câte o sarcină pentru fiecare, datată la următorul moment bun de semănat sau plantat pentru datele tale de îngheț.", ["welcome_create"] = "Creează gospodăria mea", ["welcome_later"] = "Apoi îți trasezi casa și grădina pe harta din satelit. Totul rămâne pe acest calculator.", ["welcome_offline"] = "Nu pot ajunge la serviciul de căutare. Scrie coordonatele singur sau setează-le mai târziu în profilul grădinii.", ["welcome_no_hits"] = "Nu s-a găsit nimic. Încearcă altă scriere sau scrie coordonatele.", ["welcome_picked"] = "Folosesc {0}.", ["welcome_need_name"] = "Dă mai întâi un nume gospodăriei.", ["welcome_bad_coords"] = "Latitudinea trebuie să fie între -90 și 90, longitudinea între -180 și 180.", ["welcome_task_map"] = "Trasează casa și grădina pe harta din satelit", ["welcome_task_bed"] = "Adaugă primul strat în designerul de grădină", ["welcome_task_sow"] = "{0}: {1}", ["welcome_done"] = "Gospodăria ta e gata. Începe prin a o trasa pe hartă.", ["nav_photos"] = "Fotografii", ["photos_sub"] = "Poze cu straturile, plantele, animalele și locurile tale, în ordinea datei. Adaugă una de aici sau de pe fișa unei plante sau a unor animale de pe planul grădinii.", ["photos_add"] = "Adaugă o fotografie", ["photos_add_short"] = "Adaugă poză", ["photos_all"] = "Tot", ["photos_show"] = "Arată", ["photos_search"] = "Caută în descrieri și nume", ["photos_count"] = "{0} fotografii", ["photos_caption"] = "Descriere", ["photos_about"] = "Despre", ["photos_which"] = "Care anume", ["photos_date"] = "Data pozei", ["photos_cancel"] = "Renunță", ["photos_close"] = "Închide", ["photos_k_general"] = "Grădina", ["photos_k_bed"] = "Un strat", ["photos_k_plant"] = "O plantă", ["photos_k_animal"] = "Animale", ["photos_k_place"] = "Un loc", ["photos_empty"] = "Nicio fotografie încă. Fă câte o poză fiecărui strat în fiecare lună și vei putea vedea cum a decurs sezonul,